effect.shader:
const int TAPS = 10;
void main(){
  vec2 uv = acScreenNorm;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float a = max(src.a, 1e-4);
  vec3 c = src.rgb / a;
  float ar = acScreenSize.x / max(acScreenSize.y, 1.0);
  vec3 acc = vec3(0.0);
  for (int i = 0; i < TAPS; i++){
    float t = float(i) / float(TAPS - 1);
    vec2 o = vec2(t * length, 0.0);
    acc += texture2DCv(inputImg.texture, uv + o).rgb / max(texture2DCv(inputImg.texture, uv + o).a, 1e-4);
    acc += texture2DCv(inputImg.texture, uv - o).rgb / max(texture2DCv(inputImg.texture, uv - o).a, 1e-4);
    vec2 ov = vec2(0.0, t * length);
    acc += texture2DCv(inputImg.texture, uv + ov).rgb / max(texture2DCv(inputImg.texture, uv + ov).a, 1e-4);
    acc += texture2DCv(inputImg.texture, uv - ov).rgb / max(texture2DCv(inputImg.texture, uv - ov).a, 1e-4);
  }
  acc /= float(TAPS * 4.0);
  acc *= smoothstep(threshold, 1.0, gmLum(acc));
  vec3 col = c + acc * intensity * mixAmt;
  gl_FragColor = vec4(clamp(col, 0.0, 1.0) * a, a);
}
